private void btn_ReviewMarrk_Click(object sender, EventArgs e)
{
    // Kiem tra du lieu nhap
    if (!IsValidData())
        return;

    if (MessageManager.Confirm("Bạn có muốn lấy điểm review từ phiếu đánh giá để cập nhật vào điểm rèn luyện học kỳ?") != System.Windows.Forms.DialogResult.Yes)
        return;

    string strClassID = uClass.ClassIDEditValue.ToString();
    int intYear = uYearSemester.YearIDEditValueInt32.Value;
    int intSemester = uYearSemester.SemesterEditValueInt32.Value;

    DCore.IData objDB = null;

    try
    {
        objDB = DCore.Data.CreateData();
        objDB.Connect();

        // 1. Lay Pollid tu Pol_plan theo Year + Semester
        string strSQL = String.Format(
            "Select Pol_plan.Pollid From Pol_plan Where Pol_plan.Yearid = {0} And Pol_plan.Semester = {1}",
            intYear, intSemester);
        DataTable dtbPlan = objDB.ExecQueryToDataTable(strSQL);

        if (dtbPlan.Rows.Count == 0)
        {
            MessageManager.Warning("Không tìm thấy phiếu đánh giá cho năm học và học kỳ này!");
            return;
        }

        int intPollID = Convert.ToInt32(dtbPlan.Rows[0]["Pollid"]);

        // 2. Lay danh sach Pollpartid
        strSQL = String.Format(
            "Select Pol_pollpart.Pollpartid From Pol_pollpart Where pollid = {0}", intPollID);
        DataTable dtbPollParts = objDB.ExecQueryToDataTable(strSQL);

        if (dtbPollParts.Rows.Count == 0)
        {
            MessageManager.Warning("Không tìm thấy phần đánh giá cho phiếu này!");
            return;
        }

        // Gop Pollpartid thanh chuoi cho IN clause
        string strPollPartIDs = "";
        for (int i = 0; i < dtbPollParts.Rows.Count; i++)
        {
            if (i > 0)
                strPollPartIDs += ",";
            strPollPartIDs += dtbPollParts.Rows[i]["Pollpartid"].ToString();
        }

        // 3. Lay cau hoi, xac dinh N1 -> N6 tuong ung Questionid
        strSQL = String.Format(
            "Select Pol_question.Questionid, Pol_question.Pollpartid, Pol_question.Description " +
            "From Pol_question Where Pol_question.Pollpartid In ({0})",
            strPollPartIDs);
        DataTable dtbQuestions = objDB.ExecQueryToDataTable(strSQL);

        int intQID_N1 = 0, intQID_N2 = 0, intQID_N3 = 0;
        int intQID_N4 = 0, intQID_N5 = 0, intQID_N6 = 0;

        foreach (DataRow drw in dtbQuestions.Rows)
        {
            string strDesc = drw["Description"].ToString().ToUpper();
            int intQID = Convert.ToInt32(drw["Questionid"]);

            if (strDesc.Contains("N1"))
                intQID_N1 = intQID;
            else if (strDesc.Contains("N2"))
                intQID_N2 = intQID;
            else if (strDesc.Contains("N3"))
                intQID_N3 = intQID;
            else if (strDesc.Contains("N4"))
                intQID_N4 = intQID;
            else if (strDesc.Contains("N5"))
                intQID_N5 = intQID;
            else if (strDesc.Contains("N6"))
                intQID_N6 = intQID;
        }

        // 4. Lay danh sach sinh vien trong lop
        strSQL = String.Format(
            "Select Sim_student.Studentid, Sim_student.StudentCode " +
            "From Sim_student " +
            "Where Sim_student.Isdeleted = 0 And Sim_student.Classid = '{0}'",
            strClassID.Replace("'", "''"));
