            int intMark4 = 0, intMark5 = 0, intMark6 = 0;

            DataRow[] drwMarks = dtbReviewMarks.Select("Studentid = " + intStudentID.ToString());
            foreach (DataRow drwMark in drwMarks)
            {
                int intQID = Convert.ToInt32(drwMark["Questionid"]);
                int intReviewMark = Convert.ToInt32(drwMark["Reviewmark"]);

                if (intQID == intQID_N1)
                    intMark1 = intReviewMark;
                else if (intQID == intQID_N2)
                    intMark2 = intReviewMark;
                else if (intQID == intQID_N3)
                    intMark3 = intReviewMark;
                else if (intQID == intQID_N4)
                    intMark4 = intReviewMark;
                else if (intQID == intQID_N5)
                    intMark5 = intReviewMark;
                else if (intQID == intQID_N6)
                    intMark6 = intReviewMark;
