Create Procedure Dbo.SIM_SemesterEthicMark_Review
    @ClassID varchar(50),
    @YearID int,
    @Semester int
As
Begin
    Set Nocount On;

    Declare @PollID int;
    Declare @QID_N1 int, @QID_N2 int, @QID_N3 int, @QID_N4 int, @QID_N5 int, @QID_N6 int;
    Declare @StudentID int, @StudentCode nvarchar(50);
    Declare @Mark1 int, @Mark2 int, @Mark3 int, @Mark4 int, @Mark5 int, @Mark6 int;
    Declare @Mark int;
    Declare @Level nvarchar(50);
    Declare @CreateUser nvarchar(20), @UpdateUser nvarchar(20);
    Declare @Now datetime;
    Declare @Inserted int, @Updated int;

    Set @Inserted = 0;
    Set @Updated = 0;
    Set @Now = Getdate();

    -- Lay PollID tu Pol_plan
    Select @PollID = Pollid
    From Pol_plan
    Where Yearid = @YearID And Semester = @Semester;

    If @PollID Is Null
    Begin
        Raiserror(N'Không tìm thấy phiếu đánh giá cho năm học và học kỳ này!', 16, 1);
        Return;
    End

    -- Xac dinh QuestionID cho N1 -> N6 dua vao Description
    Select
        @QID_N1 = Max(Case When Upper([Description]) Like '%N1%' Then Questionid End),
        @QID_N2 = Max(Case When Upper([Description]) Like '%N2%' Then Questionid End),
        @QID_N3 = Max(Case When Upper([Description]) Like '%N3%' Then Questionid End),
        @QID_N4 = Max(Case When Upper([Description]) Like '%N4%' Then Questionid End),
        @QID_N5 = Max(Case When Upper([Description]) Like '%N5%' Then Questionid End),
        @QID_N6 = Max(Case When Upper([Description]) Like '%N6%' Then Questionid End)
    From Pol_question
    Where Pollpartid In (
        Select Pollpartid From Pol_pollpart Where pollid = @PollID
    );

    -- Lap qua tung sinh vien trong lop
    Declare curStudent Cursor Local Fast_Forward For
    Select Studentid, StudentCode
    From Sim_student
    Where Isdeleted = 0 And Classid = @ClassID;

    Open curStudent;

    Fetch Next From curStudent Into @StudentID, @StudentCode;

    While @@Fetch_Status = 0
    Begin
        -- Reset diem
        Set @Mark1 = 0;
        Set @Mark2 = 0;
        Set @Mark3 = 0;
        Set @Mark4 = 0;
        Set @Mark5 = 0;
        Set @Mark6 = 0;

        -- Gom diem ReviewMark tu Pol_done + Pol_donedetail theo Questionid N1 -> N6
        Select
            @Mark1 = IsNull(Sum(Case When pdd.Questionid = @QID_N1 Then pdd.Reviewmark Else 0 End), 0),
            @Mark2 = IsNull(Sum(Case When pdd.Questionid = @QID_N2 Then pdd.Reviewmark Else 0 End), 0),
            @Mark3 = IsNull(Sum(Case When pdd.Questionid = @QID_N3 Then pdd.Reviewmark Else 0 End), 0),
            @Mark4 = IsNull(Sum(Case When pdd.Questionid = @QID_N4 Then pdd.Reviewmark Else 0 End), 0),
            @Mark5 = IsNull(Sum(Case When pdd.Questionid = @QID_N5 Then pdd.Reviewmark Else 0 End), 0),
            @Mark6 = IsNull(Sum(Case When pdd.Questionid = @QID_N6 Then pdd.Reviewmark Else 0 End), 0)
        From Pol_done pd
        Inner Join Pol_donedetail pdd On pd.Doneid = pdd.Doneid
        Where pd.Studentid = @StudentID And pdd.Reviewmark Is Not Null;

        -- Tinh Mark = tong Mark1..Mark6
        Set @Mark =
            IsNull(@Mark1, 0)
            + IsNull(@Mark2, 0)
            + IsNull(@Mark3, 0)
            + IsNull(@Mark4, 0)
            + IsNull(@Mark5, 0)
            + IsNull(@Mark6, 0);

        -- Xep loai Level
        If @Mark >= 90
            Set @Level = N'Xuất sắc';
        Else If @Mark >= 80
            Set @Level = N'Tốt';
        Else If @Mark >= 70
            Set @Level = N'Khá';
        Else If @Mark >= 50
            Set @Level = N'Trung bình';
        Else
            Set @Level = N'Yếu';

        -- Xac dinh CreateUser = StudentCode (max 20 ky tu)
        Set @CreateUser = Left(Ltrim(Rtrim(IsNull(@StudentCode, N''))), 20);
        If (@CreateUser Is Null Or @CreateUser = N'')
            Set @CreateUser = N'student';

        Set @UpdateUser = N'teacher';

        -- Kiem tra ton tai -> Update hoac Insert
        If Exists (Select 1
                   From Sim_semesterethicmark
                   Where Studentid = @StudentID
                     And Yearid = @YearID
                     And Semester = @Semester)
        Begin
            -- Da co -> Update
            Update Sim_semesterethicmark
            Set Mark1 = @Mark1,
                Mark2 = @Mark2,
                Mark3 = @Mark3,
                Mark4 = @Mark4,
                Mark5 = @Mark5,
                Mark6 = @Mark6,
                Mark = @Mark,
                Level = @Level,
                Updateddate = @Now,
                Updateduser = @UpdateUser
            Where Studentid = @StudentID
              And Yearid = @YearID
              And Semester = @Semester;

            Set @Updated = @Updated + 1;
        End
        Else
        Begin
            -- Chua co -> Insert
            Insert Into Dbo.Sim_semesterethicmark
            (
                Studentid, Yearid, Semester,
                Mark1, Mark2, Mark3, Mark4, Mark5, Mark6,
                Mark, Level,
                Createddate, Createduser, Updateddate, Updateduser
            )
            Values
            (
                @StudentID, @YearID, @Semester,
                @Mark1, @Mark2, @Mark3, @Mark4, @Mark5, @Mark6,
                @Mark, @Level,
                @Now, @CreateUser, @Now, @UpdateUser
            );

            Set @Inserted = @Inserted + 1;
        End

        Fetch Next From curStudent Into @StudentID, @StudentCode;
    End

    Close curStudent;
    Deallocate curStudent;

    -- Tra ve so luong Insert / Update
    Select @Inserted As InsertedCount, @Updated As UpdatedCount;

    Set Nocount Off;
End

