private void btn_ReviewMarrk_Click(object sender, EventArgs e)
{
    // Kiem tra du lieu nhap
    if (!IsValidData())
        return;

    if (MessageManager.Confirm("Bạn có muốn lấy điểm review từ phiếu đánh giá để cập nhật vào điểm rèn luyện học kỳ?") != System.Windows.Forms.DialogResult.Yes)
        return;

    string strClassID = uClass.ClassIDEditValue.ToString();
    int intYear = uYearSemester.YearIDEditValueInt32.Value;
    int intSemester = uYearSemester.SemesterEditValueInt32.Value;

    try
    {
        // Buoc 1: Goi SP chi SELECT de lay diem review (N1->N6) cua tung sv
        SIM_SemesterEthicMark obj = new SIM_SemesterEthicMark();
        DataTable dtbReview = obj.GetDataTable("POL_EthicMark_GetReviewData",
            "@ClassID", strClassID,
            "@YearID", intYear,
            "@Semester", intSemester);

        if (dtbReview == null || dtbReview.Rows.Count == 0)
        {
            MessageManager.Info("Không có dữ liệu điểm review nào để cập nhật!");
            return;
        }

        // Buoc 2: Lay du lieu diem ren luyen hien co (de co schema + kiem tra ton tai)
        DataTable dtbExisting = obj.Search(
            "@ClassID", strClassID,
            "@Year", intYear,
            "@Semester", intSemester,
            "@IsShowAllStudent", false);

        if (dtbExisting == null)
        {
            ErrorManager.Error("Không thể lấy dữ liệu điểm rèn luyện hiện có!");
            return;
        }

        // Buoc 3: Vong lap xu ly tung sinh vien
        obj.BeginTransaction();
        int intInserted = 0;
        int intUpdated = 0;

        foreach (DataRow drwReview in dtbReview.Rows)
        {
            int intStudentID = Convert.ToInt32(drwReview["Studentid"]);
            string strStudentCode = drwReview["StudentCode"].ToString();

            // Gom diem N1 -> N6
            int intM1 = Convert.ToInt32(drwReview["Mark1"]);
            int intM2 = Convert.ToInt32(drwReview["Mark2"]);
            int intM3 = Convert.ToInt32(drwReview["Mark3"]);
            int intM4 = Convert.ToInt32(drwReview["Mark4"]);
            int intM5 = Convert.ToInt32(drwReview["Mark5"]);
            int intM6 = Convert.ToInt32(drwReview["Mark6"]);

            // Tinh Mark = tong Mark1..Mark6
            int intMark = intM1 + intM2 + intM3 + intM4 + intM5 + intM6;

            // Xep loai Level
            string strLevel;
            if (intMark >= 90)
                strLevel = "Xuất sắc";
            else if (intMark >= 80)
                strLevel = "Tốt";
            else if (intMark >= 70)
                strLevel = "Khá";
            else if (intMark >= 50)
                strLevel = "Trung bình";
            else
                strLevel = "Yếu";

            // Xac dinh CreatedUser
            string strCreateUser = strStudentCode.Trim();
            if (strCreateUser.Length > 20)
                strCreateUser = strCreateUser.Substring(0, 20);
            if (String.IsNullOrEmpty(strCreateUser))
                strCreateUser = "student";

            // Tim record hien co
            DataRow[] arrFound = dtbExisting.Select("Studentid = " + intStudentID.ToString());
            DataRow drwTarget;

            if (arrFound.Length > 0)
            {
                // Da co -> cap nhat diem vao dong hien co
                drwTarget = arrFound[0];
            }
            else
            {
                // Chua co -> tao dong moi
                drwTarget = dtbExisting.NewRow();
                drwTarget["Studentid"] = intStudentID;
                dtbExisting.Rows.Add(drwTarget);
            }

            // Gan diem vao DataRow
            drwTarget["Mark1"] = intM1;
            drwTarget["Mark2"] = intM2;
            drwTarget["Mark3"] = intM3;
            drwTarget["Mark4"] = intM4;
            drwTarget["Mark5"] = intM5;
            drwTarget["Mark6"] = intM6;
            drwTarget["Mark"] = intMark;
            drwTarget["Level"] = strLevel;

            // Parse va save
            SIM_SemesterEthicMark item = new SIM_SemesterEthicMark();
            item.IDB = obj.IDB;

            if (item.Parse(drwTarget))
            {
                if (item.SemesterEthicMarkID == null)
                {
                    // Them moi
                    item.Semester = intSemester;
                    item.YearID = intYear;
                    item.CreatedUser = strCreateUser;

                    if (!item.Add())
                    {
                        ErrorManager.Error("Thêm điểm rèn luyện bị lỗi!");
                        obj.RollBackTransaction();
                        return;
                    }
                    intInserted++;
                }
                else
                {
                    // Cap nhat
                    item.UpdatedUser = UserSession.Username;

                    if (!item.Update())
                    {
                        ErrorManager.Error("Cập nhật điểm rèn luyện bị lỗi!");
                        obj.RollBackTransaction();
                        return;
                    }
                    intUpdated++;
                }
            }
            else
            {
                ErrorManager.Error("Parse dữ liệu điểm review bị lỗi!");
                obj.RollBackTransaction();
                return;
            }
        }

        obj.CommitTransaction();

        MessageManager.Info(String.Format(
            "Cập nhật điểm rèn luyện học kỳ thành công!\nThêm mới: {0} sinh viên\nCập nhật: {1} sinh viên",
            intInserted, intUpdated));

        // Nap lai du lieu
        bolIsRefresh = false;
        LoadData();
    }
    catch (Exception ex)
    {
        ErrorManager.Error("Lỗi khi cập nhật điểm review: " + ex.Message);
    }
}

